declare(strict_types=1);
ini_set('display_errors','0');require dirname(__DIR__).'/private/app.php';require dirname(__DIR__).'/private/billing/routes.php';security_headers();header('Cache-Control: no-store');header('X-Robots-Tag: noindex,nofollow');
try{
 $a=bill_actor(($_GET['mode']??'customer')!=='owner');$id=filter_var($_GET['id']??'',FILTER_VALIDATE_INT);if(!$id)crm_fail(404,'Запись не найдена.');$i=bill_invoice($a,$id);if(!$i['snapshot']||!hash_equals($i['snapshot_hash'],hash('sha256',$i['snapshot'])))crm_fail(409,'Не удалось проверить документ.');$s=json_decode($i['snapshot'],true,512,JSON_THROW_ON_ERROR);$b=bill_balance($i);
 header('Content-Type: text/html; charset=UTF-8');if(($_GET['download']??'')==='1')header('Content-Disposition: attachment; filename="invoice-'.$id.'.html"');
 $e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>НейроДело — счёт <?= $e($s['number']) ?></title><link rel="stylesheet" href="/billing.css"></head><body><main class="invoice-paper"><h1>НейроДело · Счёт <?= $e($s['number']) ?></h1><p>Выставлен: <?= $e($s['issued_at']) ?> UTC · Оплатить до <?= $e($s['due_on']) ?></p><h2>Исполнитель</h2><?php foreach(['legal_name','registration','address','tax_treatment'] as $f): ?><p><?= nl2br($e($s['merchant'][$f])) ?></p><?php endforeach; ?><h2>Заказчик</h2><p><?= $e($s['customer']['name']) ?></p><p>Заказ <?= $e($s['order']['number']) ?> — <?= $e($s['order']['title']) ?></p><table><thead><tr><th>Услуга</th><th>Количество</th><th>Цена, RUB</th><th>Сумма, RUB</th></tr></thead><tbody><?php foreach($s['lines'] as $l): ?><tr><td><?= $e($l['description']) ?></td><td><?= $e(intdiv((int)$l['quantity_milli'],1000).'.'.str_pad((string)((int)$l['quantity_milli']%1000),3,'0',STR_PAD_LEFT)) ?></td><td><?= bill_decimal((int)$l['unit_minor']) ?></td><td><?= bill_decimal((int)$l['total_minor']) ?></td></tr><?php endforeach; ?></tbody></table><h2>Итого: <?= bill_decimal((int)$s['total_minor']) ?> RUB</h2><p>Поступило: <?= bill_decimal($b['paid_minor']) ?> · Возвращено: <?= bill_decimal($b['refunded_minor']) ?> · Остаток: <?= bill_decimal($b['outstanding_minor']) ?> RUB</p><h2>Оплата</h2><p><?= nl2br($e($s['merchant']['payment_instructions'])) ?></p><p>Документ не является кассовым чеком. Печать и сохранение: Ctrl+P.</p><p class="checksum">Контрольная сумма снимка: <?= $e($i['snapshot_hash']) ?></p></main></body></html><?php
}catch(CrmFailure $e){fail($e->status,$e->getMessage());}catch(CustomerFailure $e){fail($e->status,$e->getMessage());}catch(Throwable $e){server_error($e);}
